import { CellClassParams } from 'ag-grid-community';
import { ColumnDefsConfig } from 'components';
import { cellClass } from 'components/Table/cellClass';

const countryCellClass = (params: CellClassParams) => {
  const classes = [...cellClass(params)];
  classes.push('ag-cell-country');
  return classes;
};

export const tableConfig: ColumnDefsConfig = {
  country: {
    cellClass: (params) => countryCellClass(params),
  },
};
